{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Metoprolol, a high-transfer analogue, showed mean absolute oral bioavailability of 0.50 ± 0.11 in healthy subjects, clearly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Alfuzosin absolute bioavailability was 64.5% in eight healthy subjects, supporting high oral availability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Vorapaxar absolute oral bioavailability is approximately 90% in healthy subjects, strongly supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Esaxerenone absolute bioavailability was 90.8% postprandially and 89.0% fasting in healthy Japanese subjects, well above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Benazeprilat absolute bioavailability from oral benazepril was 27.1–28.5%, the lowest high-transfer value but still above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show absolute oral bioavailability values above 20% (27–90%), with no threshold-relevant low values. The query's sulfonylurea structure is consistent with complete oral absorption, so high bioavailability is predicted.",
  "evidence_gaps": [
    "No direct experimental bioavailability record for the query molecule itself was provided.",
    "Some records use qualitative 'low' labels, but their quantitative values remain above the 20% threshold and therefore do not support a low prediction."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

